<?php

namespace App\Services\Admin;

use App\Models\Otp;
use Illuminate\Database\Eloquent\Builder;

/**
 * Read-mostly admin service: OTPs are generated by the auth flow, not
 * hand-created in the admin panel. This exposes monitoring / cleanup only.
 */
class OtpService extends BaseCrudService
{
    protected string $model = Otp::class;

    protected array $with = ['user'];

    public function purgeExpired(): int
    {
        return Otp::where('expires_at', '<', now())->delete();
    }

    protected function applyFilters(Builder $query, array $filters): Builder
    {
        return $query
            ->when($filters['type'] ?? null, fn ($q, $t) => $q->where('type', $t))
            ->when($filters['identifier'] ?? null, fn ($q, $i) => $q->where('identifier', 'like', "%{$i}%"))
            ->when(isset($filters['is_used']), fn ($q) => $q->where('is_used', (bool) $filters['is_used']));
    }
}
